'use client';

import {useEffect, useRef, useState, type ReactNode} from 'react';
import {AppShellInset, type AppShellInsetProps} from './app-shell-inset';
import {AgentRunPlan} from './agent-run/plan';
import {AgentRunActivity} from './agent-run/activity';
import {AgentRunPanel} from './agent-run/panel';
import {HeaderIcon} from './agent-run/header-icons';
import {AgentRunDiff} from './agent-run/diff';
import type {AgentRunStatus, DraftDecisions, RunDraft, RunStep, RunUser} from './agent-run/types';
import './agent-run.css';

export type {AgentRunStatus, DraftDecisions, RunApproval, RunCall, RunDraft, RunStep, RunUser} from './agent-run/types';

export interface AgentRunProps {
  title: string;
  steps: RunStep[];
  status: AgentRunStatus;
  elapsedMs: number;
  draft?: RunDraft;
  /** Set false when the host already provides application navigation. */
  shell?: boolean;
  shellProps?: Omit<AppShellInsetProps, 'children' | 'workspace' | 'user' | 'onNavigate'>;
  /** The host may own the only vertical scroll instead of this component. */
  scrollOwner?: 'component' | 'host';
  taskHeader?: ReactNode;
  rounds?: ReactNode;
  /** Replaces the built-in plan and activity; data and selection stay caller-owned. */
  process?: ReactNode;
  filePreview?: ReactNode;
  panelDetails?: ReactNode;
  panelTitle?: ReactNode;
  agent?: string;
  user?: RunUser;
  workspace?: string;
  startedAt?: string;
  cost?: string;
  toolCallCount?: number;
  undoDecisions?: DraftDecisions;
  onApprove?: (stepId: string) => void;
  onDeny?: (stepId: string, reason?: string) => void;
  onStop?: () => void;
  onRestart?: () => void;
  onRetry?: (stepId:string) => void;
  onStepsChange?: (steps: RunStep[]) => void;
  onDraftChange?: (decisions: DraftDecisions, resolvedText: string) => void;
  onNavigate?: (label: string) => void;
  className?: string;
}

const labels: Record<AgentRunStatus, string> = {idle:'Ready',running:'Running',waiting:'Needs input',completed:'Done',stopped:'Stopped',denied:'Stopped',error:'Failed'};
const defaultUser = {name:'Account'};
function clock(ms:number) {const s=Math.max(0,Math.floor(ms/1000));return `${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`;}
function doneTime(ms:number) {const s=Math.max(0,Math.floor(ms/1000));return s<60?`${s}s`:`${Math.floor(s/60)}m ${s%60}s`;}

/** Caller-owned run data: this screen never advances tools or approves actions by itself. */
export function AgentRun({title,steps,status,elapsedMs,draft,shell=true,shellProps,scrollOwner='component',taskHeader,rounds,process,filePreview,panelDetails,panelTitle,agent,user,workspace='Workspace',startedAt,cost,toolCallCount,undoDecisions,onApprove,onDeny,onStop,onRestart,onRetry,onStepsChange,onDraftChange,onNavigate,className=''}:AgentRunProps) {
  const root=useRef<HTMLDivElement>(null);
  const options=useRef<HTMLDivElement>(null);
  const optionsButton=useRef<HTMLButtonElement>(null);
  const panelToggle=useRef<HTMLButtonElement>(null);
  const panelSlot=useRef<HTMLDivElement>(null);
  const [panelOpen,setPanelOpen]=useState(true);
  const [overlay,setOverlay]=useState(false);
  const [menuOpen,setMenuOpen]=useState(false);
  const [notice,setNotice]=useState('');
  const running=status==='running'||status==='waiting';
  const pendingApprovalIndex=steps.findIndex(s=>s.status==='waiting'&&s.approval&&(s.approval.status??'pending')==='pending');
  const approvalIndex=pendingApprovalIndex>=0?pendingApprovalIndex:steps.reduce((last,s,index)=>s.approval?.status==='approved'||s.approval?.status==='denied'?index:last,-1);
  const approval=approvalIndex<0?undefined:{...steps[approvalIndex].approval!,stepId:steps[approvalIndex].id,stepIndex:approvalIndex,tool:steps[approvalIndex].tool};
  const hasPanel = Boolean(approval || draft || filePreview != null || panelDetails != null || agent !== undefined || user !== undefined || cost !== undefined || toolCallCount !== undefined);
  const panelVisible = hasPanel && panelOpen;
  function closePanel(){setPanelOpen(false);requestAnimationFrame(()=>panelToggle.current?.focus());}
  useEffect(()=>{
    if(!overlay || !panelVisible)return;
    panelSlot.current?.querySelector<HTMLButtonElement>('.ar-panel-close')?.focus({preventScroll:true});
  },[overlay,panelVisible]);
  useEffect(()=>{
    if(!root.current)return;
    let previous:boolean|undefined;
    const observer=new ResizeObserver(([entry])=>{const narrow=entry.contentRect.width<=1000;setOverlay(narrow);if(previous!==narrow){setPanelOpen(!narrow);previous=narrow;}});
    observer.observe(root.current);return()=>observer.disconnect();
  },[]);
  useEffect(()=>{
    if(!menuOpen)return;
    options.current?.querySelector<HTMLButtonElement>('[role=menuitem]')?.focus();
    const outside=(e:PointerEvent)=>{if(!options.current?.contains(e.target as Node))setMenuOpen(false);};
    const key=(e:KeyboardEvent)=>{if(e.key==='Escape'){e.preventDefault();setMenuOpen(false);optionsButton.current?.focus();}};
    document.addEventListener('pointerdown',outside);document.addEventListener('keydown',key);
    return()=>{document.removeEventListener('pointerdown',outside);document.removeEventListener('keydown',key);};
  },[menuOpen]);
  useEffect(()=>{if(!notice)return;const timer=setTimeout(()=>setNotice(''),2000);return()=>clearTimeout(timer);},[notice]);
  async function copyRun(){
    try{await navigator.clipboard.writeText(window.location.href);setNotice('Run link copied');}catch{setNotice('Could not copy run link');}
    setMenuOpen(false);
  }
  const body = <div ref={root} className="ar-run-body" onKeyDown={event=>{if(overlay&&panelVisible&&event.key==='Escape'&&!event.defaultPrevented&&!menuOpen){event.preventDefault();closePanel();}}} data-overlay={overlay} data-panel-open={panelVisible}>
        <div className="ar-run-main" inert={overlay&&panelVisible}>
          <header className="ar-run-bar">
            {taskHeader !== undefined ? <div className="ar-run-task-header">{taskHeader}</div> : <div className="ar-run-breadcrumb"><span className="ar-run-breadcrumb-icon"><HeaderIcon name="run"/></span><button type="button" onClick={()=>onNavigate?.('Runs')}>Runs</button><span className="ar-run-slash">/</span><b title={title}>{title}</b><span className="ar-run-badge" data-state={status}><i/>{labels[status]}</span></div>}
            <div className="ar-run-bar-tools">
              <span className="ar-run-time"><HeaderIcon name="clock" size={14}/>{status==='completed'?`Done in ${doneTime(elapsedMs)}`:status==='idle'?'Ready':`${startedAt?`Started ${startedAt} · `:''}${clock(elapsedMs)}`}</span>
              {running?<button type="button" className="ar-run-action" onClick={onStop} disabled={!onStop}><HeaderIcon name="stop" size={16}/>Stop run</button>:<button type="button" className="ar-run-action" onClick={onRestart} disabled={!onRestart}><HeaderIcon name="run" size={16}/>{status==='idle'?'Start run':'Run again'}</button>}
              <div className="ar-run-options" ref={options}><button type="button" ref={optionsButton} className="ar-run-icon-button" aria-label="Run options" aria-expanded={menuOpen} aria-haspopup="menu" onClick={()=>setMenuOpen(v=>!v)}><HeaderIcon name="more"/></button>
                {menuOpen&&<div className="ar-run-menu" role="menu" onKeyDown={event=>{const items=Array.from(event.currentTarget.querySelectorAll<HTMLButtonElement>('button:not(:disabled)'));const index=items.indexOf(document.activeElement as HTMLButtonElement);let next=index;if(event.key==='ArrowDown')next=(index+1)%items.length;else if(event.key==='ArrowUp')next=(index-1+items.length)%items.length;else if(event.key==='Home')next=0;else if(event.key==='End')next=items.length-1;else return;event.preventDefault();items[next]?.focus();}}><button role="menuitem" onClick={()=>void copyRun()}><HeaderIcon name="copy"/>Copy run link</button><button role="menuitem" disabled={!onNavigate} onClick={()=>{setMenuOpen(false);onNavigate?.('Share');}}><HeaderIcon name="share"/>Share</button><button role="menuitem" disabled={!onNavigate} onClick={()=>{setMenuOpen(false);onNavigate?.('Chat');}}><HeaderIcon name="chat"/>View in Chat</button></div>}
              </div>
              {hasPanel && <button ref={panelToggle} type="button" className="ar-run-icon-button ar-run-panel-toggle" aria-label={panelOpen?'Hide side panel':'Show side panel'} aria-pressed={panelOpen} onClick={()=>setPanelOpen(v=>!v)}><HeaderIcon name="panel"/></button>}
            </div>
          </header>
          <div className="ar-run-scroll"><div className="ar-run-column">
            {rounds}
            {process !== undefined ? process : <><AgentRunPlan title={title} steps={steps} status={status} elapsedMs={elapsedMs} onStepsChange={onStepsChange} onRetry={onRetry}/>
            <AgentRunActivity steps={steps} status={status} elapsedMs={elapsedMs}/></>}
          </div></div>
        </div>
        {overlay&&panelVisible&&<button type="button" className="ar-run-panel-scrim" aria-label="Close run details backdrop" tabIndex={-1} onClick={closePanel}/>}
        {panelVisible&&<div ref={panelSlot} className="ar-run-panel-slot" role={overlay?'dialog':undefined} aria-modal={overlay||undefined} aria-label={overlay?'Run details':undefined} onKeyDown={event=>{
          if(!overlay || event.key!=='Tab')return;
          const items=Array.from(event.currentTarget.querySelectorAll<HTMLElement>('button:not(:disabled),a[href],input:not(:disabled),select:not(:disabled),textarea:not(:disabled),[tabindex="0"]')).filter(node=>!node.closest('[inert]') && node.getClientRects().length>0);
          const first=items[0],last=items.at(-1);
          if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}
          else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}
        }}>
          <AgentRunPanel approval={approval} draft={draft ? <AgentRunDiff draft={draft} onChange={onDraftChange} undoDecisions={undoDecisions}/> : undefined} showApprovalPlaceholder={draft !== undefined} filePreview={filePreview} details={panelDetails} heading={panelTitle} agent={agent} user={user} cost={cost} toolCallCount={toolCallCount??steps.reduce((n,s)=>n+s.calls.length,0)} onApprove={onApprove} onDeny={onDeny} onClose={overlay?closePanel:undefined}/>
        </div>}
        <span className="ar-run-notice" role="status">{notice}</span>
      </div>;
  return <div className={`agent-run ${className}`} data-run-status={status} data-shell={shell} data-scroll-owner={scrollOwner}>
    {shell ? <AppShellInset {...shellProps} workspace={workspace} user={user??defaultUser} onNavigate={onNavigate}>{body}</AppShellInset> : body}
  </div>;
}

.agent-run{height:100%;width:100%;min-height:0;color:#171717;font-family:"Inter Variable",Inter,sans-serif;font-size:13px;line-height:1.45;text-align:left;font-weight:400;letter-spacing:normal;-webkit-font-smoothing:antialiased}
.agent-run *{box-sizing:border-box}.agent-run button{font-family:inherit}.agent-run button:disabled{cursor:default}.agent-run button:focus-visible{outline:2px solid #4469fc;outline-offset:2px}
.ar-run-body{position:relative;display:flex;flex:1;min-width:0;min-height:0;overflow:hidden;background:#fff}
.ar-run-main{display:flex;flex:1;flex-direction:column;min-width:0;min-height:0}
.ar-run-bar{height:52px;flex:none;display:flex;align-items:center;gap:12px;padding:0 12px 0 var(--ar-shell-header-inset,20px);border-bottom:1px solid #f0f0f0;white-space:nowrap}
.ar-run-breadcrumb{display:flex;align-items:center;gap:8px;flex:1;min-width:0}.ar-run-breadcrumb-icon{color:#737373;display:flex}.ar-run-breadcrumb button{padding:0;border:0;background:none;color:#737373;cursor:pointer;font-size:13.5px}.ar-run-breadcrumb button:hover{color:#171717}.ar-run-slash{color:#a3a3a3}.ar-run-breadcrumb>b{font-size:13.5px;font-weight:500;min-width:0;overflow:hidden;text-overflow:ellipsis}.ar-run-badge{display:inline-flex;gap:6px;align-items:center;flex:none;font-size:12px;font-weight:500;height:22px;margin-left:4px;padding:0 9px 0 8px;border-radius:99px;line-height:18.571px;background:#eef3ff;color:#4469fc}.ar-run-badge i{width:6px;height:6px;background:currentColor;opacity:1;border-radius:50%}.ar-run-badge[data-state=waiting]{background:rgb(217 119 6 / .1);color:#b45309}.ar-run-badge[data-state=completed]{background:rgb(22 163 74 / .1);color:#15803d}.ar-run-badge[data-state=stopped],.ar-run-badge[data-state=denied],.ar-run-badge[data-state=error]{background:#f5f5f5;color:#737373}
.ar-run-bar-tools{display:flex;align-items:center;gap:6px;flex:none}.ar-run-time{display:flex;gap:6px;align-items:center;color:#737373;font-size:13px;margin-right:6px}.ar-run-time>svg{width:14px;height:14px}.ar-run-action{display:inline-flex;align-items:center;justify-content:center;gap:6px;height:32px;padding:0 12px;border:1px solid #e5e5e5;border-radius:10px;background:white;color:#171717;font-size:13px;font-weight:500;box-shadow:0 1px 2px #0000000a;cursor:pointer;transition:background-color .14s,transform .12s}.ar-run-action:hover{background:#fafafa}.ar-run-action:active{transform:scale(.98)}.ar-run-action:disabled{opacity:.5}.ar-run-icon-button{display:grid;place-items:center;flex:none;width:28px;height:28px;padding:0;background:none;color:#737373;border:0;border-radius:8px;cursor:pointer;transition:background-color .14s,color .14s}.ar-run-icon-button:hover,.ar-run-icon-button[aria-expanded=true]{background:#f5f5f5;color:#171717}.ar-run-panel-toggle[aria-pressed=true]{background:#f5f5f5;color:#171717}
.ar-run-scroll{overflow:auto;min-height:0;flex:1;overscroll-behavior:contain;scrollbar-width:thin;scrollbar-color:#ddd transparent}.ar-run-column{width:calc(100% - 72px);max-width:680px;margin:32px auto 40px}
.ar-run-panel-slot{width:360px;display:flex;flex:none;min-height:0;overflow:hidden;background:#fff}.ar-run-panel-slot>.ar-panel{flex:none;width:360px;min-width:360px;height:100%}.ar-run-body[data-overlay=true] .ar-run-panel-slot{position:absolute;right:0;top:0;bottom:0;z-index:7;box-shadow:-16px 0 40px -24px #0003}.ar-run-body[data-overlay=true] .ar-run-time{display:none}
.ar-run-options{position:relative}.ar-run-menu{position:absolute;right:0;top:calc(100% + 6px);width:168px;padding:4px;border:1px solid #ebebeb;border-radius:12px;background:white;box-shadow:0 12px 32px -8px #0003;z-index:10;animation:ar-run-menu-in .16s ease-out}.ar-run-menu button{display:flex;align-items:center;gap:9px;width:100%;padding:8px 10px;text-align:left;border:0;border-radius:8px;background:none;color:#171717;font-size:13px;cursor:pointer}.ar-run-menu button:hover{background:#f5f5f5}.ar-run-notice{position:absolute;bottom:18px;left:50%;transform:translateX(-50%);padding:8px 12px;white-space:nowrap;border-radius:9px;background:#262626;color:white;z-index:20;box-shadow:0 2px 6px #0002}.ar-run-notice:empty{display:none}@keyframes ar-run-menu-in{from{opacity:0;transform:translateY(-3px) scale(.97)}to{opacity:1;transform:none}}
@media(max-width:600px){.ar-run-breadcrumb>b{max-width:none}.ar-run-breadcrumb-icon,.ar-run-breadcrumb>button,.ar-run-slash{display:none}.ar-run-bar{gap:12px;padding-right:8px}.ar-run-breadcrumb{gap:8px;padding-left:8px}.ar-run-column{width:calc(100% - 32px);margin-top:20px}.ar-run-panel-slot{max-width:100%}.ar-run-panel-slot>.ar-panel{width:100%;min-width:0;flex-basis:100%}.ar-run-body[data-overlay=true] .ar-run-panel-slot{width:100%!important;box-shadow:none}}
@media(prefers-reduced-motion:reduce){.ar-run-menu{animation:none}.ar-run-action,.ar-run-icon-button{transition:none}}

.ar-run-breadcrumb-icon>svg{display:block;width:15px;height:15px}.ar-run-bar{transition:padding-left .42s cubic-bezier(.22,1,.36,1)}.ar-run-action{line-height:13px;transition:background-color .16s,border-color .16s,color .16s,box-shadow .16s,transform .16s cubic-bezier(.22,1,.36,1)}.ar-run-action svg{flex:none;display:block}.ar-run-body:has(.ar-run-badge[data-state=completed]) .ar-run-action,.ar-run-body:has(.ar-run-badge[data-state=stopped]) .ar-run-action,.ar-run-body:has(.ar-run-badge[data-state=denied]) .ar-run-action{color:#fff;background:#262626;border-color:#262626}.ar-run-menu button>svg{flex:none;color:#737373}

.ar-run-panel-scrim{position:absolute;inset:0;z-index:6;border:0;border-radius:0;background:rgb(0 0 0 / .18);padding:0;cursor:default}.ar-run-body[data-overlay=true] .ar-run-panel-slot{border-radius:0 12px 12px 0;box-shadow:-1px 0 0 #ebebeb,-20px 0 40px -16px #0003}.ar-run-body[data-overlay=true] .ar-panel{border-left:0}@media(max-width:600px){.ar-run-body[data-overlay=true] .ar-run-panel-slot{border-radius:12px}}

.ar-run-body[data-overlay=true] .ar-run-panel-slot{animation:ar-run-panel-enter .42s cubic-bezier(.22,1,.36,1) both}.ar-run-panel-scrim{animation:ar-run-scrim-enter .3s ease both}@keyframes ar-run-panel-enter{from{transform:translateX(40px);opacity:0}to{transform:none;opacity:1}}@keyframes ar-run-scrim-enter{from{opacity:0}to{opacity:1}}@media(prefers-reduced-motion:reduce){.ar-run-body[data-overlay=true] .ar-run-panel-slot,.ar-run-panel-scrim{animation:none}}

/* The embedded variant fills one host surface; it adds no application landmark. */
.agent-run[data-shell=false]{display:flex;min-width:0;flex:1}
.ar-run-task-header{display:flex;align-items:center;flex:1;min-width:0;overflow:hidden}
.ar-run-task-header>*{min-width:0}
.agent-run[data-scroll-owner=host]{height:auto;min-height:100%;overflow:visible}
.agent-run[data-scroll-owner=host] .ar-run-body,.agent-run[data-scroll-owner=host] .ar-run-scroll{overflow:visible}
.agent-run[data-scroll-owner=host] .ar-run-scroll{flex:none}
.agent-run[data-scroll-owner=host] .ar-run-panel-slot{overflow:visible}
.agent-run[data-scroll-owner=host] .ar-panel{height:auto}
.agent-run[data-scroll-owner=host] .ar-panel-body{overflow:visible}
@media(prefers-reduced-motion:reduce){.ar-run-bar{transition:none}}
@media(max-width:600px){.ar-run-body[data-overlay=true] .ar-panel-header{padding-left:var(--ar-shell-header-inset,20px)}}

/* Public preview: the status dot breathes while work is active, then settles. */
.ar-run-badge[data-state=running] i,.ar-run-badge[data-state=waiting] i{animation:ar-run-breathe 1.4s ease-in-out infinite}
@keyframes ar-run-breathe{0%,100%{opacity:1}50%{opacity:.35}}
@media(prefers-reduced-motion:reduce){.ar-run-badge i{animation:none!important}}

.ar-activity {
  width: 100%;
  margin-top: 28px;
  min-width: 0;
  color: #404040;
  font-family: inherit;
  font-size: 13px;
  font-weight: 400;
  line-height: 18.571px;
}
.ar-activity *, .ar-activity *::before, .ar-activity *::after { box-sizing: border-box; }
.ar-activity-heading { display: block; margin: 0; padding: 0 0 14px; color: #a3a3a3; font-size: 12.5px; font-weight: 500; line-height: 16px; }
.ar-activity-entry { position: relative; display: flex; flex-direction: column; gap: 10px; padding: 0 0 20px 34px; animation: ar-activity-rise .42s cubic-bezier(.22,1,.36,1) both; }
.ar-activity-entry::before { content: ''; position: absolute; left: 11px; top: 26px; bottom: 4px; width: 1px; background: #ebebeb; }
.ar-activity-entry-head { display: flex; align-items: center; min-height: 22px; color: #171717; font-size: 13.5px; font-weight: 500; }
.ar-activity-number { position: absolute; top: 0; left: 0; display: grid; place-items: center; width: 23px; height: 23px; border-radius: 50%; box-shadow: inset 0 0 0 1px #ebebeb; background: #fff; color: #737373; font-size: 11.5px; font-weight: 500; transition: background-color .2s, color .2s; }
.ar-activity-number[data-done] { color: #171717; background: #f5f5f5; box-shadow: none; }
.ar-activity-note { display: flex; align-items: center; gap: 7px; font-size: 13px; color: #737373; }
.ar-activity-note[data-state="waiting"] { color: #b45309; }
.ar-activity-note[data-state="error"] { color: #b91c1c; }
.ar-activity-note[data-state="approved"] { color: #15803d; }
.ar-activity-note[data-state="approved"] .ar-tool-check { stroke: currentColor; }
.ar-activity-stopped { display: flex; align-items: center; gap: 7px; margin-left: 34px; color: #737373; font-size: 13px; }
.ar-tool-glyph { display: block; width: 14px; height: 14px; flex: none; }
.ar-tool-group { min-width: 0; font-size: 13.5px; line-height: 1.4; letter-spacing: -.006em; }
.ar-activity button { appearance: none; -webkit-tap-highlight-color: transparent; cursor: pointer; font-family: inherit; letter-spacing: inherit; text-align: left; }
.ar-activity button:focus-visible { outline: 2px solid #a3a3a3; outline-offset: 3px; }
.ar-tool-group-head { display: flex; align-items: center; gap: 9px; max-width: 100%; min-height: 36px; border: 0; border-radius: 10px; padding: 4px 10px 4px 5px; background: transparent; color: #6b6b6b; font-size: 13.5px; font-weight: 400; line-height: 1.4; transition: background-color .16s, color .16s; }
.ar-tool-group-head:hover { color: #171717; background: #f5f5f5; }
.ar-tool-stack { display: flex; align-items: center; flex: none; }
.ar-tool-icon { display: grid; place-items: center; flex: none; width: 26px; height: 26px; border-radius: 7px; background: #f5f5f5; color: #171717; box-shadow: inset 0 0 0 1px #e7e7e7; }
.ar-tool-icon > svg { display: block; width: 14px; height: 14px; }
.ar-tool-stack .ar-tool-icon { width: 24px; height: 24px; box-shadow: inset 0 0 0 1px #e7e7e7, 0 0 0 2px #fff; animation: ar-tool-pop .42s cubic-bezier(.22,1,.36,1) both; }
.ar-tool-stack .ar-tool-icon + .ar-tool-icon { margin-left: -5px; }
.ar-tool-group-title { display: flex; align-items: center; gap: 5px; min-width: 0; animation: ar-tool-in .36s cubic-bezier(.22,1,.36,1) both; }
.ar-tool-group-label { position: relative; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ar-tool-group[data-working] .ar-tool-group-label { font-weight: 500; }
.ar-tool-group-fail { color: #b91c1c; white-space: nowrap; }
.ar-tool-group-time { color: #8a8a8a; flex: none; white-space: nowrap; font-variant-numeric: tabular-nums; }
.ar-tool-chevron { flex: none; width: 14px; height: 14px; fill: none; stroke: #8a8a8a; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; transition: transform .36s cubic-bezier(.22,1,.36,1); }
.ar-tool-group-head[aria-expanded="true"] > .ar-tool-chevron, .ar-tool-head[aria-expanded="true"] > .ar-tool-chevron { transform: rotate(180deg); }
.ar-tool-body { display: grid; grid-template-rows: 0fr; opacity: 0; transition: grid-template-rows .38s cubic-bezier(.22,1,.36,1), opacity .24s; }
.ar-tool-body[data-open] { grid-template-rows: 1fr; opacity: 1; }
.ar-tool-clip { min-height: 0; overflow: hidden; }
.ar-tool-list { display: grid; gap: 8px; padding-top: 8px; }
.ar-tool { position: relative; min-width: 0; color: #6b6b6b; background: #fff; border-radius: 12px; box-shadow: inset 0 0 0 1px #e7e7e7, 0 1px 2px #0000000a; font-size: 13px; line-height: 1.4; letter-spacing: -.006em; }
