.ar-plan__foot[data-phase='error'] .ar-plan__status, .ar-plan__foot[data-phase='denied'] .ar-plan__status, .ar-plan__foot[data-phase='stopped'] .ar-plan__status { color: #c2331f; }
.ar-plan__elapsed { margin-left: auto; padding-right: 6px; white-space: nowrap; font-variant-numeric: tabular-nums; }
