.ar-plan[data-editable] .ar-plan__step:hover .ar-plan__remove, .ar-plan[data-editable] .ar-plan__step:focus-within .ar-plan__remove,
.ar-plan[data-editable] .ar-plan__step:hover .ar-plan__grip, .ar-plan[data-editable] .ar-plan__step:focus-within .ar-plan__grip { opacity: 1; }
