.ar-shell-guide-sub{color:#737373;font-size:12.5px;line-height:17px}
.ar-shell-guide-sub>span{color:#4469fc}
.ar-shell-guide-progress{display:block;height:4px;margin-top:6px;overflow:hidden;background:#f4f4f4;border-radius:2px}
.ar-shell-guide-progress>span{display:block;width:13%;height:100%;border-radius:2px;background:#536dff}
.ar-shell-setup{zoom:.86;padding:12px 4px 4px;color:#171717}
.ar-shell-setup-head{display:flex;align-items:center;justify-content:space-between;gap:12px;height:26px;padding:0 8px}
.ar-shell-setup-head>b{font-size:15px;line-height:22px;font-weight:600}
.ar-shell-sidebar .ar-shell-setup-head>button{display:grid;place-items:center;width:26px;height:26px;margin-right:-4px;padding:0;color:#737373;border-radius:7px;transition:background-color .16s,color .16s}
.ar-shell-setup-head>button:hover{background:#f4f4f4}
.ar-shell-setup-progress{height:5px;margin:10px 8px 8px;overflow:hidden;background:#ececec;border-radius:3px}
.ar-shell-setup-progress>span{display:block;width:12.5%;height:100%;background:#2f6bff;border-radius:3px}
.ar-shell-setup-group{border-radius:12px;transition:background-color .26s}
.ar-shell-setup-group[data-open=true]{background:#f6f6f7}
.ar-shell-sidebar .ar-shell-setup-group-head{display:flex;align-items:center;justify-content:space-between;gap:12px;width:100%;padding:11px 12px;border-radius:12px}
.ar-shell-setup-group-head>span{font-size:14px;line-height:20px;font-weight:600}
.ar-shell-setup-group-head>svg{color:#737373;transition:transform .32s var(--ar-shell-ease)}
.ar-shell-setup-group[data-open=true] .ar-shell-setup-group-head>svg{transform:rotate(180deg)}
.ar-shell-setup-panel{display:grid;grid-template-rows:0fr;transition:grid-template-rows .38s var(--ar-shell-ease)}
.ar-shell-setup-group[data-open=true] .ar-shell-setup-panel{grid-template-rows:1fr}
.ar-shell-setup-tasks{min-height:0;overflow:hidden}
.ar-shell-setup-tasks:after{content:'';display:block;height:8px}
.ar-shell-sidebar .ar-shell-setup-task{display:flex;align-items:flex-start;gap:12px;width:100%;padding:7px 12px;border-radius:10px;color:#262626;opacity:0;transform:translateY(-4px);transition:opacity .26s,transform .32s var(--ar-shell-ease),color .26s}
.ar-shell-setup-group[data-open=true] .ar-shell-setup-task{opacity:1;transform:none;transition-delay:.08s}
.ar-shell-setup-task>span:nth-child(2){font-size:14px;line-height:20px}
.ar-shell-sidebar .ar-shell-setup-task:disabled,.ar-shell-sidebar .ar-shell-setup-task[data-done=true]{color:#a3a3a3}
.ar-shell-setup-task[data-done=true]>span:nth-child(2){text-decoration:line-through}
.ar-shell-task-mark{display:grid;place-items:center;width:16px;height:16px;flex:none;margin-top:2px;border-radius:50%;background:#e1e3e8}
.ar-shell-task-mark svg{width:16px;height:16px}
.ar-shell-setup-task[data-done=true] .ar-shell-task-mark{color:#2f6bff;background:transparent}
.ar-shell-setup-task:disabled .ar-shell-task-mark{color:#d4d4d4;background:transparent}
.ar-shell-sr{position:absolute;width:1px;height:1px;padding:0;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
@media(max-width:900px){
  .ar-shell,.ar-shell[data-collapsed=true]{--ar-shell-header-inset:52px}
  .ar-shell-side-slot,.ar-shell[data-collapsed=true] .ar-shell-side-slot{width:0}
  .ar-shell-surface,.ar-shell[data-collapsed=true] .ar-shell-surface{margin:6px}
  .ar-shell-sidebar,.ar-shell[data-collapsed=true] .ar-shell-sidebar{position:absolute;inset:0 auto 0 0;width:264px;height:100%;padding:10px 10px 10px 12px;opacity:1;translate:-288px 0;visibility:hidden;background:#f8f8f8;border-radius:0 18px 18px 0;box-shadow:1px 0 0 #ebebeb,0 24px 48px -12px #00000047;transition:translate .38s var(--ar-shell-ease),visibility 0s .38s}
  .ar-shell-side-slot{z-index:12}
  .ar-shell-resizer{display:none}
  .ar-shell .ar-shell-open{left:15px;top:15px;opacity:1;visibility:visible;pointer-events:auto}
  .ar-shell-scrim{position:absolute;inset:0;z-index:10;display:block;background:#00000047;opacity:0;visibility:hidden;transition:opacity .3s,visibility 0s .3s}
  .ar-shell[data-drawer=true] .ar-shell-sidebar{translate:0;visibility:visible;transition:translate .42s var(--ar-shell-ease)}
  .ar-shell[data-drawer=true] .ar-shell-scrim{opacity:1;visibility:visible;transition:opacity .3s}
  .ar-shell[data-drawer=true] .ar-shell-open{opacity:0;visibility:hidden}
}
@media(prefers-reduced-motion:reduce){
  .ar-shell-side-slot,.ar-shell-sidebar,.ar-shell-sidebar *,.ar-shell-surface,.ar-shell-open,.ar-shell-scrim,.ar-shell-resizer::after{transition:none!important;animation:none!important}
}

/* Keep outgoing setup text until the shell has nearly finished closing. */
.ar-shell-guide-content[data-exiting=true]{animation:ar-shell-guide-exit .26s ease both;pointer-events:none}
@keyframes ar-shell-guide-exit{from{opacity:1}to{opacity:0}}
@media(prefers-reduced-motion:reduce){.ar-shell-guide-content[data-exiting=true]{animation:none;opacity:0}}
